/* Restaurar: puntos de restauracion en otro disco o memoria USB */
#include "z.h"
typedef struct { char mnt[16], dev[16], root[16], fs[8], label[16]; } vol_t; typedef struct { char n[120]; } pt_t;
static zwin *W; static vol_t T[12], B[16]; static int nt, nb, st = -1, sb = -1; static pt_t P[64]; static int np, sp = -1, todo = 1; static char msg[160], sub[160]; static int pct = -1, busy, cancel; static u64 lui; static char *CB;
#define LW 250
static void draw(void); static void tick(void) { u64 t = z_ms(); if (t - lui < 120) return; lui = t; zevent e; while (z_event(&e, 0)) if (e.win == (u32)W->id && e.type == EV_KEY && e.ch == 27) cancel = 1; draw(); }
static void cb(int p, const char *m) { pct = p; strncpy0(sub, m, 160); lui = 0; tick(); }
static void pdir(char *o) { snprintf(o, 120, "/%s/ZUNZUN-PUNTOS", B[sb].mnt); }
static void load_pts(void) { np = 0; if (sb >= 0) { char d[120]; pdir(d); zdirent e; for (int i = 0; np < 64 && !z_readdir(d, i, &e); i++) if (e.is_dir) strncpy0(P[np++].n, e.name, 120); for (int i = 0; i < np / 2; i++) { pt_t x = P[i]; P[i] = P[np - 1 - i]; P[np - 1 - i] = x; } } if (sp >= np) sp = -1; }
static void scan(void) { zmount m[32]; int n = z_mounts(m, 32); char ot[16] = "", ob[16] = ""; if (st >= 0) strcpy(ot, T[st].mnt); if (sb >= 0) strcpy(ob, B[sb].mnt); nt = 0; for (int i = 0; i < n && nt < 12; i++) { if (strncmp(m[i].fstype, "fat", 3)) continue; char p[60]; zdirent d; snprintf(p, 60, "/%s/ZUNZUN/KERNEL.BIN", m[i].name); if (z_stat(p, &d)) continue; vol_t *v = &T[nt++]; strcpy(v->mnt, m[i].name); strcpy(v->dev, m[i].dev); dk_root(m[i].dev, v->root); strcpy(v->label, m[i].label); } st = -1; for (int i = 0; i < nt; i++) if (!strcmp(T[i].mnt, ot)) st = i; if (st < 0 && nt) { st = 0; char sd[16]; if (dk_sys_disk(sd)) for (int i = 0; i < nt; i++) if (!strcmp(T[i].mnt, "sys")) st = i; } nb = 0; sb = -1; for (int i = 0; i < n && nb < 16; i++) { if (strncmp(m[i].fstype, "fat", 3)) continue; char r[16]; dk_root(m[i].dev, r); if (st >= 0 && !strcmp(r, T[st].root)) continue; vol_t *v = &B[nb]; strcpy(v->mnt, m[i].name); strcpy(v->dev, m[i].dev); strcpy(v->root, r); strcpy(v->label, m[i].label); if (!strcmp(v->mnt, ob)) sb = nb; nb++; } if (sb < 0 && nb) sb = 0; load_pts(); }
static void draw(void) { g_clear(W, UI_BG); g_rect(W, 0, 0, LW, W->h, UI_PANEL); g_textb(W, 10, 10, "Sistema que se protege", UI_TEXT); int y = 32; char b[120]; for (int i = 0; i < nt && i < 4; i++) { if (i == st) g_rect(W, 0, y, LW, 26, UI_ACC2); snprintf(b, 120, "/%s  %s", T[i].mnt, T[i].label); g_text(W, 10, y + 5, b, UI_TEXT); y += 26; } y = 150; g_textb(W, 10, y, "Guardar en (memoria USB)", UI_TEXT); y += 22; for (int i = 0; i < nb && i < 6; i++) { if (i == sb) g_rect(W, 0, y, LW, 26, UI_ACC2); snprintf(b, 120, "/%s  %s", B[i].mnt, B[i].label); g_text(W, 10, y + 5, b, UI_TEXT); y += 26; } if (!nb) g_text(W, 10, y + 4, "Conecta una memoria FAT", 0xB91C1C); y = 340; g_textb(W, 10, y, "Contenido del punto", UI_TEXT); ui_button(W, 10, y + 22, 112, 26, "Todo", todo ? 2 : 0); ui_button(W, 128, y + 22, 112, 26, "Solo sistema", todo ? 0 : 2); int X = LW + 14, wd = W->w - X - 12; g_textb(W, X, 10, "Puntos de restauracion", UI_TEXT); for (int i = 0; i < np && i < 13; i++) { int ry = 34 + i * 24; if (i == sp) g_rect(W, X, ry, wd, 24, UI_ACC2); g_text(W, X + 6, ry + 4, P[i].n, UI_TEXT); } if (!np) g_text(W, X, 36, "Todavia no hay puntos en esta unidad.", UI_MUTED); int by = W->h - 92; static const char *BT[] = {"Crear punto", "Restaurar", "Comprobar", "Borrar"}; for (int i = 0; i < 4; i++) ui_button(W, X + i * 116, by, 110, 30, BT[i], i < 2 ? 2 : 0); ui_button(W, X, by + 36, 232, 28, "Actualizar a esta version", 0); if (pct >= 0) { g_rect(W, X + 244, by + 45, wd - 244, 10, UI_LINE); g_rect(W, X + 244, by + 45, (wd - 244) * pct / 100, 10, UI_ACC); } zw_clip(W, X, by - 44, wd, 40); g_text(W, X, by - 42, msg, UI_TEXT); g_text(W, X, by - 24, sub, UI_MUTED); zw_noclip(W); zw_present(W); }
static const char *SYSD[] = {"ZUNZUN", "EFI", "PROGRAMAS", 0};
static int skip(const char *rel, int all) { if (!strcmp(rel, "ZUNZUN-PUNTOS") || !strcmp(rel, "DIAGNOST.TXT") || rel[0] == '.' ) return 1; if (all || strchr(rel, '/')) return 0; if (!strcmp(rel, "LEEME.TXT")) return 0; for (int i = 0; SYSD[i]; i++) if (!strcmp(rel, SYSD[i])) return 0; return 1; }
typedef void (*vfn)(const char *rel, u64 size, int dir, void *u);
static int walk(const char *root, const char *rel, int all, vfn f, void *u) { char *p = malloc(1200), *r = p + 600; snprintf(p, 600, "/%s%s%s", root, *rel ? "/" : "", rel); typedef struct { char n[256]; u64 s; int d; } ent; int cap = 64, c = 0; ent *v = malloc(cap * sizeof *v); zdirent d; while (!z_readdir(p, c, &d)) { if (c == cap) { cap *= 2; v = realloc(v, cap * sizeof *v); } strncpy0(v[c].n, d.name, 256); v[c].s = d.size; v[c].d = d.is_dir; c++; } for (int i = 0; i < c && !cancel; i++) { snprintf(r, 600, "%s%s%s", rel, *rel ? "/" : "", v[i].n); if (skip(r, all)) continue; f(r, v[i].s, v[i].d, u); if (v[i].d) walk(root, r, all, f, u); } free(v); free(p); return 0; }
static u64 T_files, T_bytes, D_bytes; static int ERR; static sb_t MF; static char PDIR[220], SRC[16];
static void count(const char *r, u64 s, int d, void *u) { if (!d) { T_files++; T_bytes += s; } }
static u32 fcrc(const char *p, u64 *len) { int f = z_open(p, O_READ); if (f < 0) { ERR = f; return 0; } u32 c = 0; long r; u64 t = 0; while ((r = z_read(f, CB, 1 << 20)) > 0) { c = z_crc_add(c, (u8 *)CB, r); t += r; D_bytes += r; if (T_bytes) pct = MIN(D_bytes * 100 / T_bytes, 99ULL); tick(); if (cancel) break; } z_close(f); if (len) *len = t; return c; }
static int fcopy(const char *a, const char *b, u32 *crc) { int f = z_open(a, O_READ); if (f < 0) return f; z_unlink(b); int g = z_open(b, O_WRITE | O_CREATE | O_TRUNC); if (g < 0) { z_close(f); return g; } long r; int e = 0; u32 c = 0; while ((r = z_read(f, CB, 1 << 20)) > 0) { c = z_crc_add(c, (u8 *)CB, r); if (z_write(g, CB, r) != r) { e = -28; break; } D_bytes += r; if (T_bytes) pct = MIN(D_bytes * 100 / T_bytes, 99ULL); tick(); if (cancel) { e = -125; break; } } if (r < 0) e = r; z_close(f); z_close(g); if (crc) *crc = c; return e; }
static void mk(const char *p) { char t[700]; strncpy0(t, p, 700); for (char *s = t + 1; *s; s++) if (*s == '/') { *s = 0; z_mkdir(t); *s = '/'; } z_mkdir(t); }
static void cpv(const char *r, u64 s, int d, void *u) { char a[700], b[900]; snprintf(b, 900, "%s/files/%s", PDIR, r); if (d) { mk(b); sb_f(&MF, "D 0 0 %s\n", r); return; } snprintf(a, 700, "/%s/%s", SRC, r); strncpy0(sub, r, 160); u32 c = 0; int e = fcopy(a, b, &c); if (e) { if (!ERR) ERR = e; return; } sb_f(&MF, "F %08x %lu %s\n", c, s, r); }
static int need(void) { if (st < 0 || sb < 0) { strcpy(msg, _("Elige el sistema y una unidad distinta para guardar")); return 0; } z_set_ro(B[sb].mnt, 0); return 1; }
static void done(const char *t) { strncpy0(msg, t, 160); busy = 0; pct = -1; sub[0] = 0; char m[220]; snprintf(m, 220, "[prueba] restaurar: %s", t); z_log(m); scan(); }
static void create(void) { if (!need()) return; u32 t[6]; z_time(t); char nm[60] = "", base[120]; if (!ui_prompt("Nuevo punto", "Nombre (opcional):", nm, 40)) return; for (char *c = nm; *c; c++) if (strchr("/\\:*?\"<>|", *c)) *c = '_'; pdir(base); snprintf(PDIR, 220, "%s/%u-%02u-%02u %02u%02u%02u%s%s", base, t[5], t[4], t[3], t[2], t[1], t[0], nm[0] ? " " : "", nm); mk(PDIR); strcpy(SRC, T[st].mnt); busy = 1; cancel = 0; ERR = 0; T_files = T_bytes = D_bytes = 0; strcpy(msg, _("Creando el punto...")); pct = 0; walk(SRC, "", todo, count, 0); MF = (sb_t){0}; sb_f(&MF, "ZPUNTO1 %s\n", todo ? "todo" : "sistema"); walk(SRC, "", todo, cpv, 0); char p[300]; snprintf(p, 300, "%s/MANIFEST.TXT", PDIR); if (!ERR && !cancel) ERR = z_writefile(p, MF.p, MF.n); u8 *boot = malloc(64 * 512); if (!z_disk_read(T[st].root, 0, 64, boot)) { snprintf(p, 300, "%s/BOOT.BIN", PDIR); z_writefile(p, boot, 64 * 512); } free(boot); free(MF.p); z_sync(); char r[160]; if (ERR || cancel) snprintf(r, 160, _("No se completo: %s"), cancel ? _("cancelado") : z_errstr(ERR)); else snprintf(r, 160, _("Punto creado: %lu archivos, %lu MB"), T_files, T_bytes >> 20); done(r); }
static u64 strtoul_(const char *s) { const char *p = strchr(strchr(s + 2, ' ') + 1 - 0, ' '); (void)p; const char *q = strchr(s + 2, ' ') + 1; u64 v = 0; while (isdigit(*q)) v = v * 10 + *q++ - '0'; return v; }
static int verify(char **out) { char p[300]; snprintf(p, 300, "%s/MANIFEST.TXT", PDIR); char *m = z_readfile(p, 0); if (!m || strncmp(m, "ZPUNTO1", 7)) { free(m); return -2; } T_files = T_bytes = D_bytes = 0; char *q = strchr(m, '\n') + 1, *s = q; while (*s) { char *e = strchr(s, '\n'); if (!e) break; if (*s == 'F') { T_bytes += strtoul_(s); T_files++; } s = e + 1; } s = q; int bad = 0; while (*s && !cancel) { char *e = strchr(s, '\n'); if (!e) break; *e = 0; if (*s == 'F') { u32 c = 0; for (const char *h = s + 2; *h != ' '; h++) c = c * 16 + (isdigit(*h) ? *h - '0' : tolower(*h) - 'a' + 10); char *r = strchr(strchr(s + 2, ' ') + 1, ' ') + 1; char f[1000]; snprintf(f, 1000, "%s/files/%s", PDIR, r); strncpy0(sub, r, 160); ERR = 0; u32 g = fcrc(f, 0); if (ERR || g != c) bad++; } *e = '\n'; s = e + 1; } if (out) *out = m; else free(m); return bad; }

static void set_pdir(void) { char b[120]; pdir(b); snprintf(PDIR, 220, "%s/%s", b, P[sp].n); }
static void do_verify(void) { if (sb < 0 || sp < 0) { strcpy(msg, _("Elige un punto")); return; } set_pdir(); busy = 1; cancel = 0; strcpy(msg, _("Comprobando...")); pct = 0; int b = verify(0); char r[120]; if (b < 0) snprintf(r, 120, _("El punto no es valido")); else if (b) snprintf(r, 120, _("Punto danado: %d archivos no coinciden"), b); else snprintf(r, 120, _("Punto correcto: %lu archivos"), T_files); done(r); }
static void rmt(const char *p) { zdirent d; if (z_stat(p, &d)) return; if (d.is_dir) { char *q = malloc(900); for (;;) { if (z_readdir(p, 0, &d)) break; snprintf(q, 900, "%s/%s", p, d.name); rmt(q); zdirent t; if (!z_stat(q, &t)) break; } free(q); } z_unlink(p); }
static void do_del(void) { if (sp < 0) return; char q[160]; snprintf(q, 160, _("Borrar el punto %.80s?"), P[sp].n); if (!ui_confirm("Borrar punto", q)) return; z_set_ro(B[sb].mnt, 0); set_pdir(); busy = 1; strcpy(msg, _("Borrando...")); draw(); rmt(PDIR); z_sync(); done("Punto borrado"); }
typedef struct { char **v; int n, cap; } names_t; static names_t KEEP;
static int kept(const char *r) { for (int i = 0; i < KEEP.n; i++) if (!strcasecmp(KEEP.v[i], r)) return 1; return 0; }
static void clean_v(const char *r, u64 s, int d, void *u) { if (d || kept(r)) return; if (!strcmp(r, "ZUNZUN/AJUSTES.TXT") || !strcmp(r, "ZUNZUN/TEMA.TXT")) return; char p[700]; snprintf(p, 700, "/%s/%s", T[st].mnt, r); z_unlink(p); sb_f(&MF, "x"); }
static int isbin(const char *r) { return !strcasecmp(r, "ZUNZUN/KERNEL.BIN") || !strcasecmp(r, "ZUNZUN/INITRD.BIN") || !strcasecmp(r, "EFI/BOOT/BOOTX64.EFI"); }
static void do_restore(void) { if (!need() || sp < 0) { if (sp < 0) strcpy(msg, _("Elige un punto")); return; } char q[200], c[16] = ""; snprintf(q, 200, _("Se restaurara /%s al punto elegido. Escribe RESTAURAR:"), T[st].mnt); if (!ui_prompt("Restaurar", q, c, 16) || strcmp(c, _("RESTAURAR"))) { strcpy(msg, _("Cancelado")); return; } set_pdir(); busy = 1; cancel = 0; ERR = 0; strcpy(msg, _("1/3 Comprobando el punto...")); pct = 0; char *m = 0; int b = verify(&m); if (b) { free(m); done(b < 0 ? "El punto no es valido" : "Punto danado: no se ha tocado nada"); return; } z_set_ro(T[st].mnt, 0); int all = !strncmp(m + 8, "todo", 4); strcpy(msg, _("2/3 Restaurando archivos...")); D_bytes = 0; KEEP.n = 0; KEEP.cap = (int)T_files + 2048; KEEP.v = malloc(KEEP.cap * sizeof(char *)); char *s = strchr(m, '\n') + 1; int chg = 0, bins = 0, fails = 0; while (*s && !cancel) { char *e = strchr(s, '\n'); if (!e) break; *e = 0; char kind = *s; char *h = s + 2, *z = strchr(h, ' '), *rel = strchr(z + 1, ' ') + 1; u32 cc = 0; for (const char *x = h; x < z; x++) cc = cc * 16 + (isdigit(*x) ? *x - '0' : tolower(*x) - 'a' + 10); char a[1000], d[700]; snprintf(a, 1000, "%s/files/%s", PDIR, rel); snprintf(d, 700, "/%s/%s", T[st].mnt, rel); if (KEEP.n < KEEP.cap) KEEP.v[KEEP.n++] = rel; if (kind == 'D') mk(d); else { strncpy0(sub, rel, 160); ERR = 0; u64 sv = D_bytes; u32 cur = fcrc(d, 0); int same = !ERR && cur == cc; ERR = 0; D_bytes = sv; if (isbin(rel)) { if (!same) bins = 1; } else if (!same) { char par[700]; strcpy(par, d); *strrchr(par, '/') = 0; mk(par); int r = fcopy(a, d, 0); if (r) fails++; else chg++; } } s = e + 1; } if (all && !cancel) { MF = (sb_t){0}; walk(T[st].mnt, "", 1, clean_v, 0); chg += MF.n; free(MF.p); } int e = 0; if (bins && !cancel) { strcpy(msg, _("3/3 Restaurando el arranque...")); char k[300], i[300], u[300], bo[300]; snprintf(k, 300, "%s/files/ZUNZUN/KERNEL.BIN", PDIR); snprintf(i, 300, "%s/files/ZUNZUN/INITRD.BIN", PDIR); snprintf(u, 300, "%s/files/EFI/BOOT/BOOTX64.EFI", PDIR); snprintf(bo, 300, "/rd/inst/boot.bin"); e = dk_update_system(T[st].mnt, T[st].dev, k, i, u, bo, cb); } z_sync(); free(KEEP.v); free(m); char r[160]; if (cancel) strcpy(r, _("Interrumpido: conviene repetir la restauracion")); else if (e || fails) snprintf(r, 160, _("Con errores: %d archivos, arranque %s"), fails, e ? z_errstr(e) : _("bien")); else snprintf(r, 160, _("Restaurado: %d cambios%s. Reinicia el equipo."), chg, bins ? _(" y sistema") : ""); done(r); }
static void do_update(void) { if (st < 0) return; if (!strcmp(T[st].mnt, "sys") && 0) return; char q[160], c[16] = ""; snprintf(q, 160, _("Instalar esta version en /%s sin tocar tus datos? Escribe ACTUALIZAR:"), T[st].mnt); if (!ui_prompt("Actualizar", q, c, 16) || strcmp(c, _("ACTUALIZAR"))) return; busy = 1; strcpy(msg, _("Actualizando...")); int e = dk_update_system(T[st].mnt, T[st].dev, "/rd/inst/KERNEL.BIN", "/rd/inst/INITRD.BIN", "/rd/inst/BOOTX64.EFI", "/rd/inst/boot.bin", cb); char r[120]; snprintf(r, 120, e ? "Error: %s" : _("Sistema actualizado%s. Reinicia."), e ? z_errstr(e) : ""); done(r); }
int main(const char *a) { CB = malloc(1 << 20); W = zw_new("Restaurar", -1, 0, 800, 470, WF_DECOR | WF_RESIZE); scan(); strcpy(msg, _("Guarda los puntos en una memoria USB, fuera del disco del sistema.")); draw(); zevent e; int X = LW + 14; for (;;) { if (!z_event(&e, 3000)) { if (!busy) { scan(); draw(); } continue; } if (e.type == EV_REDRAW) { draw(); continue; } if (e.win != (u32)W->id) continue; if (e.type == EV_CLOSE) return 0; if (e.type == EV_RESIZE) { zw_resized(W, e.x, e.y); draw(); continue; } if (e.type != EV_DOWN) continue; int by = W->h - 92; if (e.x < LW) { if (e.y >= 32 && e.y < 136) { int i = (e.y - 32) / 26; if (i < nt) { st = i; scan(); } } else if (e.y >= 172 && e.y < 328) { int i = (e.y - 172) / 26; if (i < nb) { sb = i; sp = -1; load_pts(); } } else if (e.y >= 362 && e.y < 388) todo = e.x < 125; } else if (e.y >= by && e.y < by + 30) { int i = (e.x - X) / 116; if (i == 0) create(); else if (i == 1) do_restore(); else if (i == 2) do_verify(); else if (i == 3) do_del(); } else if (e.y >= by + 36 && e.y < by + 64 && e.x < X + 232) do_update(); else if (e.y >= 34 && e.y < by - 46) { int i = (e.y - 34) / 24; sp = i < np ? i : -1; } draw(); } }
